#include <iostream>

void scaleElement(double* ptr, double factor) {
    if (ptr != nullptr) {
        *ptr *= factor;
    }
}

int main() {
    double val = 7.3;
    double* fPtr = &val;

    std::cout << "Original value: " << *fPtr << "\n";
    scaleElement(fPtr, 2.0);
    std::cout << "Modified value: " << val << "\n";

    constexpr std::size_t SIZE = 3;
    double numbers[SIZE] = {1.1, 2.2, 3.3};
    double* nPtr = numbers; // decay to &numbers[0]

    std::cout << "First element via pointer: " << *nPtr << "\n";
    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    constexpr std::size_t SIZE = 5;
    double numbers[SIZE] = {0.0, 1.1, 2.2, 3.3, 4.4};
    double* nPtr = numbers;

    std::cout << std::fixed << std::setprecision(1);

    // 4 equivalent notations for index 3 (4th element)
    std::cout << "Array subscript: " << numbers[3] << "\n";
    std::cout << "Array pointer/offset: " << *(numbers + 3) << "\n";
    std::cout << "Pointer subscript: " << nPtr[3] << "\n";
    std::cout << "Pointer offset: " << *(nPtr + 3) << "\n";

    // Void pointer cast demonstration
    void* vPtr = &numbers[2];
    std::cout << "Void ptr cast: " << *static_cast<double*>(vPtr) << "\n";

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // String literal initialized as array
    char vowel1[] = "AEIOU";
    char vowel2[] = {'A', 'E', 'I', 'O', 'U', '\0'};

    std::cout << "vowel1: " << vowel1 << " (sizeof: " << sizeof(vowel1) << ")\n";
    std::cout << "vowel2: " << vowel2 << " (sizeof: " << sizeof(vowel2) << ")\n";

    // Safe pointer to string literal
    const char* phrase = "C++ Pointers";
    std::cout << "Literal via const char*: " << phrase << "\n";

    return 0;
}
